package org.dextur.reputation.application;
import java.nio.file.*;
import java.util.*;
import org.dextur.reputation.domain.PlayerLanguage;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class RecoveryConfigurationTest {
 @org.junit.jupiter.api.io.TempDir Path directory;
 String defaults()throws Exception{return new String(getClass().getResourceAsStream("/recovery.yml").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}
 @Test void defaultsAreSafeAndAllStagesComeFromData()throws Exception{var rules=RecoveryConfiguration.load(directory);assertTrue(rules.enabled());assertEquals(-100,rules.threshold());assertEquals(108000,rules.minimumPlaySeconds());assertEquals(604800,rules.minimumAgeSeconds());assertFalse(rules.automatic());assertEquals(30,rules.maximumProgramReward());assertEquals(150,rules.maximumLifetimeReward());assertEquals(List.of("stabilization","consistency","restoration"),rules.program().stages().stream().map(s->s.id()).toList());}
 @Test void disabledAndCustomConfigurationAreNotOverwritten()throws Exception{Files.writeString(directory.resolve("recovery.yml"),defaults().replace("enabled: true","enabled: false").replace("reputation: 5","reputation: 2"));var before=Files.readString(directory.resolve("recovery.yml"));assertFalse(RecoveryConfiguration.load(directory).enabled());assertEquals(2,RecoveryConfiguration.load(directory).program().stages().getFirst().reputation());assertEquals(before,Files.readString(directory.resolve("recovery.yml")));}
 @Test void invalidVersionDuplicateIdsUnavailableTypesAndCrossFieldsFail()throws Exception{for(String text:List.of(defaults().replace("config-version: 1","config-version: 2"),defaults().replace("id: consistency","id: stabilization"),defaults().replace("type: ACTIVE_PLAYTIME","type: TRADES"),defaults().replace("maximum-active-programs: 1","maximum-active-programs: 2"),defaults().replace("timezone: UTC","timezone: Invalid/Zone"),defaults().replace("maximum-lifetime-recovery: 150","maximum-lifetime-recovery: 1"),defaults().replace("suspicious-signal: NONE","suspicious-signal: CANCEL"))){Files.writeString(directory.resolve("recovery.yml"),text);assertThrows(Exception.class,()->RecoveryConfiguration.load(directory));}}
 @Test void unavailableExternalObjectiveRemainsAnExplicitProviderRequirement()throws Exception{Files.writeString(directory.resolve("recovery.yml"),defaults().replace("type: ACTIVE_PLAYTIME","type: EXTERNAL\n            provider: contracts\n            provider-version: 1\n            configuration: {mode: verified}"));var rules=RecoveryConfiguration.load(directory);assertEquals("contracts",rules.program().stages().getFirst().objectives().getFirst().provider());}
 @Test void bothCatalogsCompleteAndSubstitutionsAreLiteral()throws Exception{var ru=YamlFiles.resource("/lang/ru_RU.yml");var en=YamlFiles.resource("/lang/en_US.yml");var keys=ru.keySet().stream().filter(k->k.startsWith("recovery-")).collect(java.util.stream.Collectors.toSet());assertFalse(keys.isEmpty());assertEquals(keys,en.keySet().stream().filter(k->k.startsWith("recovery-")).collect(java.util.stream.Collectors.toSet()));var messages=Messages.bundled(PlayerLanguage.ru_RU);var hostile="<click:run_command:'/op attacker'>name</click>";for(var locale:PlayerLanguage.values()){var c=messages.content(locale,"recovery-error",Map.of("reason",hostile));assertTrue(DisplayFormatter.plain(c).contains(hostile));assertNull(c.clickEvent());}}
 @Test void oldLocaleFilesReceiveAdditiveRecoveryKeysWithoutLosingCustomText()throws Exception{Files.createDirectories(directory.resolve("lang"));for(var locale:PlayerLanguage.values()){String text=new String(getClass().getResourceAsStream("/lang/"+locale+".yml").readAllBytes());text=text.replaceAll("(?m)^recovery-[^\\n]+\\n?","");Files.writeString(directory.resolve("lang/"+locale+".yml"),text);}var messages=new Messages(directory.resolve("lang"),PlayerLanguage.ru_RU);assertEquals("Восстановление репутации",messages.plain(PlayerLanguage.ru_RU,"recovery-title"));}
}
